import{z as s,x as i,o as l,c as p,q as r,j as t,D as a,d as B,s as A,S as n,b as e}from"./chunks/framework.C8m1ZpeB.js";const f=JSON.parse('{"title":"推理引擎在 RL 循环里","description":"","frontmatter":{"title":"推理引擎在 RL 循环里","date":"2026-09-18T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/rlsys-inference-in-loop.md","filePath":"llm/rlsys-inference-in-loop.md","lastUpdated":1791413859000}'),D={name:"llm/rlsys-inference-in-loop.md"};function d(C,E,m,h,u,c){const o=i("Mermaid");return l(),p("div",null,[E[2]||(E[2]=r('<h1 id="推理引擎在-rl-循环里" tabindex="-1">推理引擎在 RL 循环里 <a class="header-anchor" href="#推理引擎在-rl-循环里" aria-label="Permalink to &quot;推理引擎在 RL 循环里&quot;">​</a></h1><div class="epigraph"><p>推理引擎为在线服务的首 token 延迟而生，RL 训练要的是离线批生成的吞吐与可复现——同一个引擎，两套诉求，接错就两头吃亏。</p><footer>—— 据 Kwon 等 vLLM（SOSP 2023）与 verl、slime 的接入形态整理</footer></div><p><a href="/llm/rlsys-replay-batching">上一课</a>把经验组成了更新批次，而批次上游的吞吐取决于生成端。本课下到引擎层：vLLM、SGLang 这类推理引擎坐进 RL 循环当 rollout 后端。服务的三大件——连续批处理、PagedAttention、前缀缓存——原样搬进来用，但 RL 换了一组 SLO：没有等在屏幕前的用户，却有一份必须精确返回的行为 logprob，和一批必须对齐版本的权重。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>服务默认与 RL 需求在四处打架。采样参数：服务里是产品体验（温度低点、回答稳点），RL 里是算法的探索策略，\\(\\tau\\) 与 top-\\(p\\) 直接决定熵与组内方差，按服务直觉调参会把探索调没。logprob：服务端是可选项，RL 必须逐 token 返回采样时的 logprob，引擎内部的批重组与调度优化不得改变它。权重更新：服务假定权重终身不变，RL 每隔几步整体换权重，换完之后 KV 与前缀缓存全部作废。显存：引擎为 KV cache 留满显存，训练相需要这份显存还回去。四处都是接口语义问题，不是性能微调。</p><p><span class="marginnote">常见误区：初学者容易把温度当「服务质量旋钮」，按服务直觉调低求稳。在 RL 里 \\(\\tau\\) 与 top-\\(p\\) 是算法超参：调得太低，组内响应千篇一律，方差趋零、优势归零，梯度没了信号——探索不是副作用，它就是学习原料本身。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>四个对应。采样：把 \\(\\tau\\)、top-\\(p\\)、随机种子写进运行配置而不是请求参数，批内固定、跨实验只动这一个旋钮（<a href="/llm/rl-sampling-temperature">采样温度与探索</a>是它的算法面）。logprob：请求级打开 logprobs 选项，随序列落盘进经验缓冲；验收加一条断言——训练器随机抽样本，用声称的版本离线重算 logprob 与缓存比对。权重：走引擎的原位更新接口（collective 广播或重切分），换完递增版本号，协议见 <a href="/llm/rollout-weight-sync">rollout 引擎与权重同步</a>。显存：sleep 类接口让引擎在训练相释放权重与 KV，生成相唤醒重载，峰值显存从「两份权重加两份状态」降为两相取最大（<a href="/llm/rollout-resource-sharing">Rollout 与训练资源复用</a>）。前缀缓存对 RL 意外友好：同提示组内 \\(G\\) 个响应共享前缀，命中率天然高。长度与停止是请求语义的一部分：<code>max_tokens</code> 与 stop 要在引擎层强制（<a href="/llm/length-budget-rl">长度预算与截断</a>），不靠模型自觉。</p><p><span class="marginnote">「连续批处理」翻译成大白话：普通批处理要等一整批全部生成完才放下一批进来；连续批处理每完成一条就立刻补一条新请求进批，像食堂窗口腾出一个座位就放一位新客人，GPU 始终满负荷。它管理的是吞吐与显存碎片，不是用户延迟。</span></p><p><span class="marginnote">验收推理引擎接入的最小断言集：固定种子下同请求可复现；返回 logprob 与离线重算一致（容小数值差）；换权重后旧前缀缓存确已失效（用「改权重后答案应变化」的探针请求验证）。三条任一不过，训练静默出错。</span></p>',10)),(l(),t(n,null,{default:a(()=>[A(o,{id:"mermaid-28",class:"mermaid",graph:"flowchart%20TD%0A%20%20CFG%5B%22%E8%BF%90%E8%A1%8C%E9%85%8D%E7%BD%AE%EF%BC%9A%E6%B8%A9%E5%BA%A6%2Ftop-p%2F%E7%A7%8D%E5%AD%90%22%5D%20--%3E%20ENG%5B%22%E6%8E%A8%E7%90%86%E5%BC%95%E6%93%8E%EF%BC%9A%E8%BF%9E%E7%BB%AD%E6%89%B9%E5%A4%84%E7%90%86%20%2B%20%E5%89%8D%E7%BC%80%E7%BC%93%E5%AD%98%22%5D%0A%20%20TR%5B%22%E8%AE%AD%E7%BB%83%E5%99%A8%22%5D%20--%3E%7C%22%E5%8E%9F%E4%BD%8D%E6%8D%A2%E6%9D%83%E9%87%8D%EF%BC%8C%E7%89%88%E6%9C%AC%20%2B1%22%7C%20ENG%0A%20%20ENG%20--%3E%7C%22%E5%BA%8F%E5%88%97%20%2B%20%E9%80%90%20token%20logprob%22%7C%20BUF%5B%22%E7%BB%8F%E9%AA%8C%E7%BC%93%E5%86%B2%22%5D%0A%20%20ENG%20--%3E%20SLEEP%5B%22%E8%AE%AD%E7%BB%83%E7%9B%B8%20sleep%EF%BC%9A%E9%87%8A%E6%94%BE%E6%9D%83%E9%87%8D%E4%B8%8E%20KV%22%5D%0A%20%20SLEEP%20--%3E%7C%22%E5%94%A4%E9%86%92%E9%87%8D%E8%BD%BD%20v_k%2B1%22%7C%20ENG%0A"})]),fallback:a(()=>[...E[0]||(E[0]=[B(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=e("h2",{id:"机制",tabindex:"-1"},[B("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),E[4]||(E[4]=e("p",null,"引擎在 RL 循环里的价值要按「每 token 生成成本加版本切换开销」联合计价。连续批处理与分页 KV 压前者：组内并发生成把 \\(G\\) 个响应塞进同一批波浪，KV 按页分配避免按最大长度预留。sleep 与原位换权重压后者：若换权重走「导出文件再重载」，一次几十秒，几千次迭代累计不可接受；原位 collective 更新把切换压到秒级。两者的交互有一个隐蔽点：引擎的内部重排与 chunked prefill 不改变给定前缀的条件分布，但浮点求和顺序会带来数值级差异——logprob 断言要设小的数值容差，不能要求逐位相等，也不能不设断言。",-1)),E[5]||(E[5]=e("p",null,[e("span",{class:"marginnote"},"数字实例看前缀缓存的价值：组内 \\(G=8\\) 个响应共享同一提示。若提示有 2000 token，无缓存时要算 \\(8\\times2000=16000\\) 个前缀 token；命中缓存只需算 1 次，各响应从自己的第一个新 token 起步——同一提示采多个响应的 RL 设置，天然是前缀缓存的最佳场景。")],-1)),(l(),t(n,null,{default:a(()=>[A(o,{id:"mermaid-38",class:"mermaid",graph:"flowchart%20LR%0A%20%20subgraph%20NA%5B%22%E4%B8%8D%E5%81%9A%E8%B5%84%E6%BA%90%E5%A4%8D%E7%94%A8%EF%BC%9A%E5%B3%B0%E5%80%BC%20%3D%20%E4%B8%A4%E4%BB%BD%E6%9D%83%E9%87%8D%20%2B%20%E4%B8%A4%E4%BB%BD%E7%8A%B6%E6%80%81%22%5D%0A%20%20%20%20A1%5B%22%E8%AE%AD%E7%BB%83%E7%9B%B8%EF%BC%9A%E8%AE%AD%E7%BB%83%E5%99%A8%20%2B%20%E5%BC%95%E6%93%8E%E5%90%8C%E6%97%B6%E9%A9%BB%E7%95%99%22%5D%20--%3E%20A2%5B%22%E7%94%9F%E6%88%90%E7%9B%B8%EF%BC%9A%E5%BC%95%E6%93%8E%E7%85%A7%E5%B8%B8%E6%8C%81%E6%BB%A1%20KV%20%E6%98%BE%E5%AD%98%22%5D%0A%20%20%20%20A2%20--%3E%20A3%5B%22%E6%80%BB%E5%B3%B0%E5%80%BC%20%E2%89%88%20%E4%B8%A4%E8%80%85%E4%B9%8B%E5%92%8C%EF%BC%8C%E8%B0%81%E4%B9%9F%E4%B8%8D%E8%AE%A9%E8%B0%81%22%5D%0A%20%20end%0A%20%20subgraph%20WB%5B%22sleep%20%2F%20%E5%94%A4%E9%86%92%EF%BC%9A%E5%B3%B0%E5%80%BC%20%3D%20%E4%B8%A4%E7%9B%B8%E5%8F%96%E6%9C%80%E5%A4%A7%22%5D%0A%20%20%20%20B1%5B%22%E7%94%9F%E6%88%90%E7%9B%B8%EF%BC%9A%E5%BC%95%E6%93%8E%E6%8C%81%E6%9D%83%E9%87%8D%E4%B8%8E%20KV%EF%BC%8C%E8%AE%AD%E7%BB%83%E5%99%A8%E8%AE%A9%E4%BD%8D%22%5D%20--%3E%20B2%5B%22%E6%8D%A2%E6%9D%83%E9%87%8D%E5%90%8E%20sleep%EF%BC%9A%E9%87%8A%E6%94%BE%E6%9D%83%E9%87%8D%E4%B8%8E%20KV%22%5D%0A%20%20%20%20B2%20--%3E%20B3%5B%22%E8%AE%AD%E7%BB%83%E7%9B%B8%EF%BC%9A%E8%AE%AD%E7%BB%83%E5%99%A8%E7%8B%AC%E5%8D%A0%E6%98%BE%E5%AD%98%EF%BC%8C%E5%94%A4%E9%86%92%E6%97%B6%E5%86%8D%E9%87%8D%E8%BD%BD%22%5D%0A%20%20end%0A"})]),fallback:a(()=>[...E[1]||(E[1]=[B(" Loading... ",-1)])]),_:1})),E[6]||(E[6]=r('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>引擎层不改变采样分布的数学：温度与 top-p 仍是算法的一部分，引擎只是忠实执行。服务的 SLO（首 token 延迟、公平排队）在 RL 里大多无意义，但连续批处理仍值得保留——它管理的是显存碎片与波浪调度，不是用户延迟。换引擎不是无损替换：采样实现与调度细节的差异足以改变探索行为，跨引擎对比要重跑基线。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>推理引擎进 RL 循环，SLO 从用户延迟换成吞吐、logprob 精确性与版本对齐。</li><li>采样参数是算法超参：进配置、固定种子、单旋钮改动；别按服务直觉调。</li><li>行为 logprob 逐 token 返回并缓存，配离线重算断言；权重走原位更新，版本号递增。</li><li>sleep 与唤醒控制显存峰值；前缀缓存对组内共享前缀天然友好，换权重后必须验证缓存失效。</li><li>出处：Kwon 等，vLLM，SOSP 2023；Sheng 等，HybridFlow，EuroSys 2025；据 verl、slime 实现整理。</li></ul>',4))])}const g=s(D,[["render",d]]);export{f as __pageData,g as default};
